INSERT INTO dump_descriptions (base_key, description) VALUES ('bp_mod_manager', 'Adds an in-game manager that lists loaded mods, opens their settings pages, and lets players enable or disable mods that allow it; it also manages the menu key and notifications.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('custom_enemy_cap', 'Adds configurable enemy and swarmer caps with HUD counts; the host removes excess enemies and can lower the caps when frame rate drops.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('callformommy', 'Replaces Bosco’s eight call-back sound cues with custom audio.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
